from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 4))
    a = []
    for v in range(1, n + 1):
        a += [v, v, v]
    perm = draw(st.permutations(a))
    return f"{n}\n{' '.join(map(str, perm))}\n"

def validate(inp):
    try:
        t = inp.split()
        if len(t) < 1:
            return False
        n = int(t[0])
        if not (1 <= n <= 10**5):
            return False
        if len(t) != 1 + 3 * n:
            return False
        a = [int(x) for x in t[1:]]
        if any(not (1 <= x <= n) for x in a):
            return False
        cnt = [0] * (n + 1)
        for x in a:
            cnt[x] += 1
        return all(cnt[i] == 3 for i in range(1, n + 1))
    except Exception:
        return False

def ref(inp):
    t = inp.split()
    n = int(t[0])
    a = [int(x) for x in t[1:]]
    f = {}
    for i in range(1, n + 1):
        pos = [j for j in range(len(a)) if a[j] == i]
        f[i] = pos[1]
    order = sorted(range(1, n + 1), key=lambda i: f[i])
    return ' '.join(map(str, order))
